/**
 * Host-side command gate. Classifies inbound slash commands and gates
 * them before they reach the container.
 *
 * - Filtered commands: dropped silently (never reach the container)
 * - Admin commands: checked against user_roles; denied senders get a
 *   "Permission denied" response written directly to messages_out
 * - Intercept commands: handled by a registered handler before fan-out
 * - Normal messages: pass through unchanged
 */
import { hasAdminPrivilege, isAnyAdmin } from './modules/permissions/db/user-roles.js';

export type GateResult =
  | { action: 'pass' }
  | { action: 'filter' }
  | { action: 'deny'; command: string }
  | { action: 'intercept'; handlerName: string; command: string; args: string };

export type InterceptHandler = (ctx: InterceptContext) => Promise<void>;

export interface InterceptContext {
  userId: string;
  replyMessagingGroupId: string;
  command: string;
  args: string;
}

const INTERCEPT_COMMANDS: Map<string, { handlerName: string; requiresAuth: 'admin' | 'any' }> = new Map([
  ['/dashboard-token', { handlerName: 'dashboard_token_issue', requiresAuth: 'admin' }],
]);

const interceptHandlers = new Map<string, InterceptHandler>();

export function registerInterceptHandler(name: string, h: InterceptHandler): void {
  interceptHandlers.set(name, h);
}

export function getInterceptHandler(name: string): InterceptHandler | undefined {
  return interceptHandlers.get(name);
}

export function clearInterceptHandlers(): void {
  interceptHandlers.clear();
}

const FILTERED_COMMANDS = new Set(['/start', '/help', '/login', '/logout', '/doctor', '/config', '/remote-control']);
const ADMIN_COMMANDS = new Set(['/clear', '/compact', '/context', '/cost', '/files', '/upload-trace']);

/**
 * For threaded chat-sdk inbounds, the message text the agent sees is wrapped
 * with prior thread context:
 *   `[Thread context]\nassistant: <prev>\n[Latest message]\n<user text>`
 * The gate functions classify the USER's text, not the wrapped form, so peel
 * off everything before the final `[Latest message]\n` marker. Plain (non-
 * threaded) inbounds have no marker and pass through unchanged.
 */
function extractUserMessage(text: string): string {
  const marker = '[Latest message]\n';
  const idx = text.lastIndexOf(marker);
  if (idx === -1) return text;
  return text.substring(idx + marker.length).trim();
}

/**
 * Strip leading mention tokens from message text. Discord/Slack inboxes deliver
 * messages like `<@U123> /dashboard-token` or `@bot /clear` — the slash command
 * is the second token, not the first. Without stripping, both gates' first-char
 * check would mis-classify these as plain prose and route them to the agent.
 *
 * Strips both formal (`<@123>`, `<@!123>`, `<@U08H7SULNER|name>`) and bare
 * (`@bot ` followed by whitespace) mention prefixes. Iterates so that multi-
 * mention prefixes (`@bot1 @bot2 /command`) all get stripped.
 */
function stripLeadingMentions(text: string): string {
  let prev: string;
  let cur = text;
  do {
    prev = cur;
    cur = cur.replace(/^\s*<@[!&]?[\w-]+(\|[^>]*)?>\s*/, ''); // Discord/Slack formal mention
    cur = cur.replace(/^\s*@[\w-]+\s+/, ''); // bare @name followed by whitespace
  } while (prev !== cur);
  return cur;
}

/**
 * Pre-fan-out gate: runs ONCE per inbound message, before the agent fan-out loop.
 * Handles INTERCEPT_COMMANDS (e.g. /dashboard-token) and FILTERED_COMMANDS.
 * ADMIN_COMMANDS are NOT intercepted here — they flow through to gateCommand at fan-out.
 */
export function preFanoutGate(content: string, userId: string): GateResult {
  let text: string;
  try {
    const parsed = JSON.parse(content);
    text = (parsed.text || '').trim();
  } catch {
    text = content.trim();
  }

  text = extractUserMessage(text);
  text = stripLeadingMentions(text);

  if (!text.startsWith('/')) return { action: 'pass' };

  const parts = text.split(/\s+/);
  const command = (parts[0] ?? '').toLowerCase();
  const args = parts.slice(1).join(' ');

  if (FILTERED_COMMANDS.has(command)) return { action: 'filter' };

  const intercept = INTERCEPT_COMMANDS.get(command);
  if (intercept) {
    if (intercept.requiresAuth === 'admin') {
      if (!isAnyAdmin(userId)) return { action: 'deny', command };
    }
    return { action: 'intercept', handlerName: intercept.handlerName, command, args };
  }

  return { action: 'pass' };
}

/**
 * Classify a message and decide whether it should reach the container.
 * Returns 'pass' for normal messages and authorized admin commands,
 * 'filter' for silently-dropped commands, 'deny' for unauthorized
 * admin commands.
 */
export function gateCommand(content: string, userId: string | null, agentGroupId: string): GateResult {
  let text: string;
  try {
    const parsed = JSON.parse(content);
    text = (parsed.text || '').trim();
  } catch {
    text = content.trim();
  }

  text = extractUserMessage(text);
  text = stripLeadingMentions(text);

  if (!text.startsWith('/')) return { action: 'pass' };

  const command = text.split(/\s/)[0].toLowerCase();

  if (FILTERED_COMMANDS.has(command)) return { action: 'filter' };

  if (ADMIN_COMMANDS.has(command)) {
    if (isAdmin(userId, agentGroupId)) {
      return { action: 'pass' };
    }
    return { action: 'deny', command };
  }

  // Unknown slash commands pass through (the agent/SDK handles them)
  return { action: 'pass' };
}

function isAdmin(userId: string | null, agentGroupId: string): boolean {
  if (!userId) return false;
  return hasAdminPrivilege(userId, agentGroupId);
}

}

// 2. Sender resolution (permissions module upserts the users row as a
//    side effect so later role/access lookups find a real record).
//    Without the module, userId is null — downstream tolerates it.
const userId: string | null = senderResolver ? senderResolver(event) : null;

// 2a. Eagerly populate the user_dms cache for inbound 1:1 DMs. The cache
//     was historically only written lazily by ensureUserDm() on the
//     outbound-DM path (approvals, DMs we initiate), which meant
//     features depending on "is this messaging_group the user's DM?"
//     (Slack user-token gate, future per-user DM features) would
//     incorrectly deny on a first-time inbound DM until something else
//     prewarmed the cache. Writing here makes the cache reliable.
//
//     Guard: require event.isDM === true explicitly (not just
//     mg.is_group === 0). The messaging-group creation path defaults
//     is_group to 0 when the adapter doesn't pass isDM (line above
//     this branch — `event.isDM === false ? 1 : 0`), so is_group=0
//     can mean "uncertain adapter" rather than "confirmed DM." Caching
//     a shared channel as a user's DM would poison subsequent DM
//     resolution. (Codex P2 catch on PR #108 follow-up.)
if (userId !== null && event.isDM === true) {
  try {
    const { upsertUserDm } = await import('./modules/permissions/db/user-dms.js');
    upsertUserDm({
      user_id: userId,
      channel_type: mg.channel_type,
      messaging_group_id: mg.id,
      resolved_at: new Date().toISOString(),
    });
  } catch (err) {
    // Permissions module not installed — downstream features that depend
    // on this cache will just see no row. Non-fatal.
    log.debug('router: skipped user_dms upsert (permissions module unavailable)', { err: String(err) });
  }
}

// 2b. Pre-fan-out intercept gate: runs ONCE per inbound, before agents
//     are resolved. Handles /dashboard-token and other INTERCEPT_COMMANDS.
//     FILTERED commands are dropped. Unknown/ADMIN commands fall through.
if (userId !== null && (event.message.kind === 'chat' || event.message.kind === 'chat-sdk')) {
  const preGate = preFanoutGate(event.message.content, userId);
  if (preGate.action === 'intercept') {
    const handler = getInterceptHandler(preGate.handlerName);
    if (handler) {
      const ctx: InterceptContext = {
        userId,
        replyMessagingGroupId: mg.id,
        command: preGate.command,
        args: preGate.args,
      };
      try {
        await Promise.race([
          handler(ctx),
          new Promise<never>((_, reject) => setTimeout(() => reject(new Error('intercept handler timeout')), 5000)),
        ]);
      } catch (err) {
        const isTimeout = err instanceof Error && err.message === 'intercept handler timeout';
        if (isTimeout) {
          log.warn('Intercept handler timed out', { handlerName: preGate.handlerName, command: preGate.command });
        } else {
          log.error('Intercept handler threw', {
            handlerName: preGate.handlerName,
            command: preGate.command,
            err: err instanceof Error ? err.message : String(err),
          });
        }
      }
    } else {
      log.warn('No intercept handler registered', { handlerName: preGate.handlerName });
    }
    return;
  }
  if (preGate.action === 'filter') {
    log.debug('Pre-fanout filtered command dropped');
    return;
  }
  if (preGate.action === 'deny') {
    log.info('Pre-fanout intercept denied (not admin)', { command: preGate.command, userId });
    return;
  }
  // 'pass' — fall through to fan-out
}

// 3. Fetch wired agents in full (we already know the count is > 0; now
//    we need their actual rows for fan-out).
const agents = getMessagingGroupAgents(mg.id);

// 4. Fan-out: evaluate each wired agent independently against engage_mode,
//    sender_scope, and access gate. An agent that engages gets its own
//    session and container wake. An agent that declines but has
//    ignored_message_policy='accumulate' still gets the message stored in
//    its session (trigger=0) so the context is available when it does
//    engage later. Drop policy = skip silently.
//
//    Subscribe (for mention-sticky wirings on threaded platforms) fires
//    once per message from this loop — the first engaging mention-sticky
//    wiring triggers adapter.subscribe(...); subsequent wirings don't
//    re-subscribe (chat.subscribe is idempotent anyway, but the flag
//    avoids the extra await).

